Interactive Live Demo
The widget below runs entirely in your browser using Shinylive (Python + Shiny compiled to WebAssembly). It fetches fresh data directly from SNIIM, parses the HTML response, and displays the result — no server required.
Choose a market, pick a month and year, and click Fetch Data to see live prices.






ImportantLive network request from your browser



Shinylive sends the HTTP request from inside your browser session. If SNIIM is unavailable or returns an error, the app will show a message explaining the issue.


#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 700

import requests
from bs4 import BeautifulSoup
from urllib.parse import urlencode
import pandas as pd
from shiny import App, ui, render, reactive

# ── Constants ────────────────────────────────────────────────────────────────

SEARCH_URL  = "https://www.economia-sniim.gob.mx/Sniim-anANT/e_SelAzu.asp"
RESULTS_URL = "https://www.economia-sniim.gob.mx/Sniim-anANT/e_Azucar03.asp"
HEADERS = {"User-Agent": "Mozilla/5.0", "Accept-Language": "es-MX,es;q=0.9"}

# ── Helpers ──────────────────────────────────────────────────────────────────

def fetch_markets():
    r = requests.get(SEARCH_URL, headers=HEADERS, timeout=20)
    r.raise_for_status()
    soup = BeautifulSoup(r.text, "html.parser")
    select = soup.find("select", {"name": "mercado"})
    if not select:
        return []
    return [
        {"id": opt.get("value", "").strip(), "label": opt.get_text(strip=True)}
        for opt in select.find_all("option")
        if opt.get("value", "").strip() not in ("", "-1")
    ]

def build_url(mercado_id, mes, anio, dia1="01", dia2="31"):
    params = {
        "producto": "1", "ingenio": "1",
        "mercado": mercado_id, "dia1": dia1, "dia2": dia2,
        "mes": mes, "anio": anio, "detalle": "S", "x": "45", "y": "15",
    }
    return f"{RESULTS_URL}?{urlencode(params)}"

def parse_html(html):
    soup = BeautifulSoup(html, "html.parser")
    tables = soup.find_all("table", {"border": "1"})
    rows = []
    for table in tables:
        mc = table.find("td", {"class": "encabDES"})
        if not mc:
            continue
        pc = table.find("td", {"class": "encabTIP"})
        product = pc.get_text(strip=True) if pc else "Desconocido"
        header_row = next(
            (r for r in table.find_all("tr") if r.find("td", {"class": "encabTAB"})),
            None,
        )
        if not header_row:
            continue
        cols = [" ".join(c.get_text(strip=True).split())
                for c in header_row.find_all("td", {"class": "encabTAB"})]
        for row in table.find_all("tr"):
            cells = row.find_all(["td", "th"], class_=["Datos", "DatosNum"])
            if len(cells) &lt; 3:
                continue
            rec = dict(zip(cols, [c.get_text(strip=True) for c in cells[:3]]))
            rec["Mercado"] = mc.get_text(strip=True)
            rec["Tipo Producto"] = product
            rows.append(rec)
    if not rows:
        return pd.DataFrame()
    df = pd.DataFrame(rows)
    if "Fecha" in df.columns:
        df["Fecha"] = pd.to_datetime(df["Fecha"], format="%d/%m/%Y", errors="coerce")
    price_col = next((c for c in df.columns if "Precio" in c), None)
    if price_col:
        df[price_col] = pd.to_numeric(
            df[price_col].str.replace(",", "", regex=False), errors="coerce"
        )
    return df

# ── UI ───────────────────────────────────────────────────────────────────────

YEARS  = [str(y) for y in range(2020, 2026)]
MONTHS = {
    "01": "January", "02": "February", "03": "March",    "04": "April",
    "05": "May",     "06": "June",     "07": "July",     "08": "August",
    "09": "September","10": "October", "11": "November", "12": "December",
}

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.h5("Query Parameters"),
        ui.input_select("market_id", "Market ID", choices={"100": "Loading markets…"}),
        ui.input_select("year",  "Year",  choices=YEARS,  selected="2025"),
        ui.input_select("month", "Month", choices=MONTHS, selected="01"),
        ui.input_slider("day_start", "Start day", min=1, max=31, value=1),
        ui.input_slider("day_end",   "End day",   min=1, max=31, value=31),
        ui.input_action_button("fetch", "Fetch Data", class_="btn-primary w-100 mt-2"),
        ui.hr(),
        ui.output_text("status"),
        width=280,
    ),
    ui.navset_tab(
        ui.nav_panel(
            "Table",
            ui.output_data_frame("data_table"),
        ),
        ui.nav_panel(
            "Price Chart",
            ui.output_plot("price_chart", height="400px"),
        ),
        ui.nav_panel(
            "Query URL",
            ui.output_code("query_url"),
        ),
    ),
    title="SNIIM Azúcar — Live Query",
    fillable=True,
)

# ── Server ───────────────────────────────────────────────────────────────────

def server(input, output, session):
    # Load markets once on startup
    @reactive.effect
    async def _load_markets():
        try:
            markets = fetch_markets()
            choices = {m["id"]: f"{m['id']} — {m['label']}" for m in markets}
            ui.update_select("market_id", choices=choices, selected="100")
        except Exception as e:
            ui.update_select("market_id", choices={"err": f"Error: {e}"})

    # Reactive data fetch (only on button click)
    result = reactive.value(pd.DataFrame())
    error_msg = reactive.value("")

    @reactive.effect
    @reactive.event(input.fetch)
    def _fetch():
        error_msg.set("")
        try:
            url = build_url(
                input.market_id(),
                str(input.month()).zfill(2),
                str(input.year()),
                str(input.day_start()).zfill(2),
                str(input.day_end()).zfill(2),
            )
            r = requests.get(url, headers=HEADERS, timeout=30)
            r.raise_for_status()
            df = parse_html(r.text)
            result.set(df)
            if df.empty:
                error_msg.set("No data returned for this query.")
        except Exception as e:
            error_msg.set(f"Error: {e}")
            result.set(pd.DataFrame())

    @output
    @render.text
    def status():
        if error_msg():
            return f"⚠ {error_msg()}"
        df = result()
        if df.empty:
            return "Click 'Fetch Data' to load."
        return f"✓ {len(df)} rows loaded."

    @output
    @render.data_frame
    def data_table():
        df = result()
        if df.empty:
            return render.DataGrid(pd.DataFrame())
        display = df.copy()
        if "Fecha" in display.columns:
            display["Fecha"] = display["Fecha"].dt.strftime("%Y-%m-%d")
        return render.DataGrid(display, filters=True, width="100%")

    @output
    @render.plot
    def price_chart():
        import matplotlib.pyplot as plt
        import matplotlib.dates as mdates

        df = result()
        fig, ax = plt.subplots(figsize=(8, 4))

        if df.empty or "Fecha" not in df.columns:
            ax.text(0.5, 0.5, "No data — fetch first",
                    ha="center", va="center", transform=ax.transAxes, fontsize=13)
            ax.axis("off")
            return fig

        price_col = next((c for c in df.columns if "Precio" in c), None)
        if price_col is None:
            ax.text(0.5, 0.5, "Price column not found",
                    ha="center", va="center", transform=ax.transAxes, fontsize=13)
            ax.axis("off")
            return fig

        daily = (
            df.groupby("Fecha")[price_col]
            .agg(["median", "min", "max"])
            .reset_index()
        )
        ax.fill_between(daily["Fecha"], daily["min"], daily["max"],
                        alpha=0.18, color="#2c7bb6", label="Min–Max range")
        ax.plot(daily["Fecha"], daily["median"],
                color="#2c7bb6", linewidth=2, marker="o", markersize=4,
                label="Daily median")
        ax.set_xlabel("Date")
        ax.set_ylabel("Price (MXN / 50 kg)")
        ax.set_title("Sugar Prices by Day", fontsize=12, fontweight="bold")
        ax.xaxis.set_major_formatter(mdates.DateFormatter("%b %d"))
        plt.xticks(rotation=30, ha="right")
        ax.legend(framealpha=0.9)
        ax.grid(axis="y", linestyle="--", alpha=0.5)
        fig.tight_layout()
        return fig

    @output
    @render.code
    def query_url():
        return build_url(
            input.market_id(),
            str(input.month()).zfill(2),
            str(input.year()),
            str(input.day_start()).zfill(2),
            str(input.day_end()).zfill(2),
        )

app = App(app_ui, server)
